class Record:
    def __init__(self, record_id, parent_id):
        self.record_id = record_id
        self.parent_id = parent_id


class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.children = []


def BuildTree(records):
    if not records:
        return None

    # Sort by record_id to make validations easier and to ensure children are appended in order
    records_sorted = sorted(records, key=lambda r: r.record_id)
    ids = [r.record_id for r in records_sorted]
    n = len(ids)

    # IDs must start at 0 and be continuous 0..n-1
    if ids[0] != 0 or ids != list(range(n)):
        raise ValueError("Record id is invalid or out of order.")

    # Prepare nodes
    nodes = [Node(i) for i in range(n)]

    # Validate parent relationships
    for r in records_sorted:
        rid = r.record_id
        pid = r.parent_id

        # Root record validations
        if rid == 0:
            if pid != 0:
                raise ValueError("Record id is invalid or out of order.")
            continue

        # Non-root: parent_id equal to record_id is only allowed for root
        if pid == rid:
            raise ValueError("Only root should have equal record and parent id.")

        # parent_id must be smaller than record_id
        if pid > rid:
            raise ValueError("Node parent_id should be smaller than its record_id.")

        # parent_id must be within valid range
        if pid < 0 or pid >= n:
            raise ValueError("Record id is invalid or out of order.")

    # Attach children in order of record id (records_sorted ensures ascending child ids)
    for r in records_sorted:
        if r.record_id == 0:
            continue
        parent = nodes[r.parent_id]
        child = nodes[r.record_id]
        parent.children.append(child)

    return nodes[0]
